-- SCAE - Esquema MySQL / MariaDB (segun el documento de requisitos)
CREATE DATABASE IF NOT EXISTS scae CHARACTER SET utf8mb4;
USE scae;
CREATE TABLE usuarios(id_usuario INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,rol ENUM('director','docente','admin') NOT NULL,estado ENUM('activo','inactivo') DEFAULT 'activo',fecha_creacion DATETIME DEFAULT CURRENT_TIMESTAMP,ultimo_acceso DATETIME NULL);
CREATE TABLE docentes(id_docente INT AUTO_INCREMENT PRIMARY KEY,id_usuario INT NOT NULL,nombres VARCHAR(100),apellidos VARCHAR(100),cedula VARCHAR(20) UNIQUE,email VARCHAR(100),telefono VARCHAR(20),especialidad VARCHAR(100),foto VARCHAR(255),anios_experiencia INT,fecha_contratacion DATE,FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario));
CREATE TABLE estudiantes(id_estudiante INT AUTO_INCREMENT PRIMARY KEY,codigo_estudiante VARCHAR(20) UNIQUE NOT NULL,nombres VARCHAR(100),apellidos VARCHAR(100),cedula VARCHAR(20),fecha_nacimiento DATE,genero ENUM('M','F'),foto VARCHAR(255),estado ENUM('activo','retirado') DEFAULT 'activo');
CREATE TABLE cursos(id_curso INT AUTO_INCREMENT PRIMARY KEY,nombre_curso VARCHAR(100),paralelo VARCHAR(10),nivel VARCHAR(50),aula VARCHAR(20),capacidad INT);
CREATE TABLE docente_curso(id_asignacion INT AUTO_INCREMENT PRIMARY KEY,id_docente INT,id_curso INT,materia VARCHAR(100),gestion VARCHAR(10),FOREIGN KEY(id_docente) REFERENCES docentes(id_docente),FOREIGN KEY(id_curso) REFERENCES cursos(id_curso));
CREATE TABLE estudiante_curso(id_inscripcion INT AUTO_INCREMENT PRIMARY KEY,id_estudiante INT,id_curso INT,gestion VARCHAR(10),FOREIGN KEY(id_estudiante) REFERENCES estudiantes(id_estudiante),FOREIGN KEY(id_curso) REFERENCES cursos(id_curso));
CREATE TABLE asistencia_docente(id_asistencia_doc INT AUTO_INCREMENT PRIMARY KEY,id_docente INT,fecha DATE,hora_entrada TIME,hora_salida TIME,estado ENUM('presente','tardanza','ausente','permiso'),observacion TEXT,registrado_por INT,FOREIGN KEY(id_docente) REFERENCES docentes(id_docente),FOREIGN KEY(registrado_por) REFERENCES usuarios(id_usuario));
CREATE TABLE asistencia_estudiante(id_asistencia_est INT AUTO_INCREMENT PRIMARY KEY,id_estudiante INT,id_curso INT,id_docente INT,fecha DATE,estado ENUM('presente','tardanza','ausente','justificado'),hora_registro TIME,observacion TEXT,UNIQUE KEY uq_dia(id_estudiante,id_curso,fecha),FOREIGN KEY(id_estudiante) REFERENCES estudiantes(id_estudiante),FOREIGN KEY(id_curso) REFERENCES cursos(id_curso),FOREIGN KEY(id_docente) REFERENCES docentes(id_docente));
CREATE TABLE log_actividades(id_log INT AUTO_INCREMENT PRIMARY KEY,id_usuario INT,accion VARCHAR(255),fecha DATETIME DEFAULT CURRENT_TIMESTAMP);
